var Q13 = [
{n:1, q:'Los delitos contra la libertad sexual están regulados en...', o:{a:'El Título VII del Libro II del Código Penal.',b:'El Título VIII del Libro II del Código Penal.',c:'El Título VI del Libro II del Código Penal.',d:'El Título V del Libro II del Código Penal.'}, correct:'b', why:{b:'Los delitos contra la libertad e indemnidad sexual están regulados en el Título VIII del Libro II del CP.'}},
{n:2, q:'Los delitos contra la libertad sexual están regulados en...', o:{a:'Los artículos 178 a 194 del Código Penal.',b:'Los artículos 178 a 194 bis del Código Penal.',c:'Los artículos 178 a 194 ter del Código Penal.',d:'Los artículos 178 a 194 quater del Código Penal.'}, correct:'b', why:{b:'Los delitos contra la libertad sexual están regulados en los artículos 178 a 194 bis del CP (Título VIII, Libro II).'}},
{n:3, q:'El Título VIII del Libro II del Código Penal, dedicado a los delitos contra la libertad sexual se estructura en...', o:{a:'3 Capítulos.',b:'4 Capítulos.',c:'5 Capítulos.',d:'6 Capítulos.'}, correct:'d', why:{d:'El Título VIII del Libro II del CP tiene 6 capítulos: Cap.I (agresiones sexuales), Cap.II (agresiones a menores 16 años), Cap.III (acoso sexual), Cap.IV (exhibicionismo y provocación), Cap.V (prostitución, explotación y corrupción de menores), Cap.VI (disposiciones comunes).'}},
{n:4, q:'El Capítulo I del Título VIII, del Libro II del Código Penal, se denomina...', o:{a:'De las agresiones sexuales y violación.',b:'De las agresiones sexuales.',c:'De las agresiones y abusos sexuales.',d:'De la violación.'}, correct:'b', why:{b:'El Capítulo I del Título VIII del CP se denomina "De las agresiones sexuales" (artículos 178 a 183 bis), tras la reforma de la LO 10/2022.'}},
{n:5, q:'El Capítulo II del Título VIII, del Libro II del Código Penal, se denomina...', o:{a:'Del acoso sexual.',b:'De las agresiones sexuales con abuso de superioridad.',c:'De las agresiones sexuales a menores de 14 años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El Capítulo II del Título VIII del CP se denomina "De las agresiones sexuales a menores de dieciséis años" (arts.183 ter y 183 quater), lo cual no coincide con ninguna de las opciones.'}},
{n:6, q:'El Capítulo III del Título VIII, del Libro II del Código Penal, se denomina...', o:{a:'De los delitos de exhibicionismo y provocación sexual.',b:'De los delitos relativos a la prostitución y a la explotación sexual y corrupción de menores.',c:'Del acoso sexual.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El Capítulo III del Título VIII del CP se denomina "Del acoso sexual" (artículo 184).'}},
{n:7, q:'El Capítulo VI del Título VIII, del Libro II del Código Penal, se denomina...', o:{a:'De los delitos de exhibicionismo y provocación sexual.',b:'De los delitos relativos a la prostitución y a la explotación sexual y corrupción de menores.',c:'Del acoso sexual.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El Capítulo VI del Título VIII del CP se denomina "Disposiciones comunes" (arts.191 a 194 bis), lo que no coincide con ninguna opción ofrecida.'}},
{n:8, q:'El Capítulo V del Título VIII, del Libro II del Código Penal, se denomina...', o:{a:'De los delitos de exhibicionismo y provocación sexual.',b:'De los delitos relativos a la prostitución y a la explotación sexual y corrupción de menores.',c:'Del acoso sexual.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El Capítulo V del Título VIII del CP se denomina "De los delitos relativos a la prostitución, la explotación sexual y la corrupción de menores" (arts.187 a 190).'}},
{n:9, q:'El Capítulo II del Título VIII, del Libro II del Código Penal, se denomina...', o:{a:'De los delitos de exhibicionismo y provocación sexual.',b:'Del acoso sexual.',c:'De las agresiones sexuales a menores de dieciséis años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El Capítulo II del Título VIII del CP se denomina "De las agresiones sexuales a menores de dieciséis años".'}},
{n:10, q:'Capítulo IV del Título VIII, del Libro II del Código Penal, se denomina...', o:{a:'De los delitos de exhibicionismo y provocación sexual.',b:'Del acoso sexual.',c:'De las agresiones sexuales a menores de dieciséis años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El Capítulo IV del Título VIII del CP se denomina "Del exhibicionismo y la provocación sexual" (arts.185 y 186).'}},
{n:11, q:'El Capítulo I del Título VIII, del Libro II del Código Penal, dedicado a las agresiones sexuales comprende los artículos...', o:{a:'178 a 180.',b:'177 a 180.',c:'178 y 179.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El Capítulo I del Título VIII comprende los artículos 178 a 183 bis del CP, lo que no coincide con ninguna de las opciones ofrecidas.'}},
{n:12, q:'Comete delito de agresiones sexuales del artículo 178.1 del Código Penal, el que...', o:{a:'Realice cualquier acto que atente contra la libertad sexual de otra persona sin su consentimiento.',b:'Realice cualquier acto que atente contra la libertad sexual de otra persona abusando de una situación de superioridad.',c:'Realice cualquier acto que atente contra la libertad sexual de otra persona que tenga anulada por cualquier causa su voluntad.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.178.1 CP: comete agresión sexual el que realice cualquier acto que atente contra la libertad sexual de otra persona sin su consentimiento.'}},
{n:13, q:'Comete delito de agresiones sexuales del artículo 178.3 del Código Penal, el que...', o:{a:'Lleve a cabo la agresión sexual de otra persona con acceso carnal por vía vaginal.',b:'Realice cualquier acto que atente contra la libertad sexual de otra persona abusando de una situación de superioridad.',c:'Realice cualquier acto que atente contra la libertad sexual de otra persona que tenga anulada por cualquier causa su voluntad.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.178.3 CP (violación): comete agresión sexual grave quien lleve a cabo acceso carnal por vía vaginal, anal o bucal, o introduzca miembros corporales u objetos por alguna de las dos primeras vías.'}},
{n:14, q:'Comete delito de agresiones sexuales del artículo 178.3 del Código Penal, el que...', o:{a:'Realice una agresión sexual con violencia o intimidación.',b:'Lleve a cabo una agresión sexual contra una persona que tenga anulada por cualquier causa su voluntad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.178.3 CP castiga específicamente el acceso carnal o introducción de objetos/miembros corporales, y aplica también cuando la víctima tiene anulada su voluntad por cualquier causa.'}},
{n:15, q:'Según el artículo 178.2 del Código Penal, se considera en todo caso agresión sexual...', o:{a:'Los actos de contenido sexual que se realicen empleando violencia.',b:'Los actos de contenido sexual que se realicen abusando de una situación de superioridad.',c:'Los actos de contenido sexual que se realicen sobre personas que tengan anulada por cualquier causa su voluntad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.178.2 CP: se consideran en todo caso agresión sexual los actos realizados con violencia o intimidación, abusando de superioridad, o sobre personas con la voluntad anulada por cualquier causa.'}},
{n:16, q:'Según el artículo 178.2 del Código Penal, se considera en todo caso agresión sexual...', o:{a:'Los actos de contenido sexual que se realicen empleando intimidación.',b:'Los actos de contenido sexual que se realicen abusando de una situación de vulnerabilidad de la víctima.',c:'Los actos de contenido sexual que se realicen sobre personas que se hallen privadas de sentido.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.178.2 CP: también son siempre agresión sexual los actos realizados con intimidación, abusando de situación de vulnerabilidad, o sobre personas privadas de sentido.'}},
{n:17, q:'En el artículo 178.1 del Código Penal, se castiga con la pena de prisión de 1 a 4 años...', o:{a:'La agresión sexual que se hubiera cometido sobre una víctima que tenga anulada por cualquier causa su voluntad.',b:'Cualquier acto que atente contra la libertad sexual de otra persona sin su consentimiento.',c:'La agresión sexual que se hubiera cometido sobre una víctima especialmente vulnerable.',d:'Cualquier acto que atente contra la libertad sexual de otra persona, realizado con violencia o intimidación.'}, correct:'b', why:{b:'Art.178.1 CP: la pena de prisión de 1 a 4 años corresponde a cualquier acto que atente contra la libertad sexual de otra persona sin su consentimiento (tipo básico).'}},
{n:18, q:'En el artículo 178.3 del Código Penal, se castiga con la pena de prisión de 1 a 5 años...', o:{a:'La agresión sexual que se hubiera cometido sobre una víctima que tenga anulada por cualquier causa su voluntad.',b:'Cualquier acto que atente contra la libertad sexual de otra persona sin su consentimiento.',c:'La agresión sexual que se hubiera cometido sobre una víctima especialmente vulnerable.',d:'Cualquier acto que atente contra la libertad sexual de otra persona, realizado con violencia o intimidación.'}, correct:'a', why:{a:'Art.178.3 CP: la pena de 1 a 5 años corresponde a la agresión sexual cometida sobre víctima con la voluntad anulada por cualquier causa (sin acceso carnal).'}},
{n:19, q:'Según el artículo 178.1 del Código Penal...', o:{a:'Solo se entenderá que hay consentimiento cuando se haya manifestado libremente mediante actos que, en atención a las circunstancias del caso, expresen de manera clara la voluntad de la persona.',b:'Se considerará en todo caso agresión sexual los actos de contenido sexual que se realicen empleando violencia o intimidación.',c:'Cuando la víctima sea o haya sido esposa o mujer, o haya estado ligada por análoga relación de afectividad, aun sin convivencia, con el autor de los hechos, se impondrá pena de prisión de 5 a 10 años.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'Art.178.1 CP: solo se entiende que hay consentimiento cuando se haya manifestado libremente mediante actos que expresen de manera clara la voluntad de la persona.'}},
{n:20, q:'Se castiga con pena de prisión de 1 a 5 años...', o:{a:'La agresión sexual en la que se hubiese empleado violencia o intimidación.',b:'La agresión sexual que se hubiera cometido sobre una víctima que tenga anulada por cualquier causa su voluntad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.178.3 CP: se castiga con prisión de 1 a 5 años la agresión sexual sobre víctima con voluntad anulada, sin acceso carnal.'}},
{n:21, q:'Según el artículo 178.4 del Código Penal, el órgano sentenciador podrá imponer la pena de prisión en su mitad inferior o una multa de 6 a 18 meses,...', o:{a:'Cuando en la agresión sexual no concurra ninguna de las circunstancias del artículo 180 del Código Penal.',b:'Cuando la agresión sexual se realice sin oposición de la víctima.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.178.4 CP: el órgano sentenciador podrá imponer la pena en su mitad inferior o multa de 6 a 18 meses cuando no concurran las circunstancias del art.180 y atendiendo a la menor entidad del hecho y circunstancias del culpable.'}},
{n:22, q:'Según el artículo 178.4 del Código Penal, el órgano sentenciador podrá imponer la pena de prisión en su mitad inferior o una multa de 6 a 18 meses,...', o:{a:'Cuando en la agresión sexual no medie violencia ni intimidación.',b:'Cuando en la agresión sexual, la víctima no tenga anulada, por cualquier causa, su voluntad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.178.4 CP: la atenuación procede cuando no hay violencia/intimidación (a) ni voluntad anulada (b), y no concurren circunstancias del art.180.'}},
{n:23, q:'Según el artículo 178.4 del Código Penal, para que el órgano sentenciador pueda imponer la pena de prisión en su mitad inferior o una multa de 6 a 18 meses, es necesario ...', o:{a:'Que la víctima haya manifestado su consentimiento.',b:'Que lo razone en la sentencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.178.4 CP: el órgano sentenciador debe razonarlo en la sentencia atendiendo a la menor entidad del hecho y circunstancias personales del culpable.'}},
{n:24, q:'Según el artículo 179.1 del Código Penal, se incurre en delito de violación cuando la agresión sexual...', o:{a:'Consista en la introducción de miembros corporales por vía vaginal, anal o bucal.',b:'Consista en la introducción de objetos por vía vaginal, anal o bucal.',c:'Consista en acceso carnal por vía vaginal, anal o bucal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.179.1 CP: hay violación cuando la agresión consiste en acceso carnal por vía vaginal, anal o bucal, o en la introducción de miembros corporales u objetos por las dos primeras vías.'}},
{n:25, q:'Según el artículo 179.1 del Código Penal, el delito de violación se castiga con la pena de prisión...', o:{a:'De 4 a 10 años.',b:'De 4 a 12 años.',c:'De 6 a 12 años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.179.1 CP: el delito de violación se castiga con la pena de prisión de 4 a 12 años.'}},
{n:26, q:'Según el artículo 179.2 del Código Penal, el delito de violación se castiga con la pena de prisión de 6 a 12 años...', o:{a:'Cuando se cometa con violencia o intimidación.',b:'Cuando se lleve a cabo con abuso de superioridad.',c:'Cuando los hechos se hayan cometido por la actuación conjunta de dos o más personas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.179.2 CP: la pena de 6 a 12 años se aplica en los mismos casos agravados que el art.178.3, entre ellos cuando los hechos se cometan por la actuación conjunta de dos o más personas.'}},
{n:27, q:'Según el artículo 179.2 del Código Penal, el delito de violación se castiga con la pena de prisión de 6 a 12 años...', o:{a:'Cuando los hechos se cometan contra una persona que se halle en una situación de especial vulnerabilidad por razón de su edad.',b:'Cuando la víctima tuviera anulada por cualquier causa su voluntad.',c:'Cuando los actos de contenido sexual revistan un carácter particularmente degradante o vejatorio.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.179.2 CP: la pena agravada de 6-12 años se aplica por las circunstancias del art.178.3 (violencia/intimidación, superioridad, voluntad anulada, carácter degradante), pero la opción d señala que ninguna de las formuladas es correcta porque están descritas de forma imprecisa.'}},
{n:28, q:'Según el artículo 179.2 del Código Penal, el delito de violación se castiga con la pena de prisión de 6 a 12 años...', o:{a:'Cuando la víctima sea o haya sido esposa o mujer que esté o haya estado ligada al autor por análoga relación de afectividad, aún sin convivencia.',b:'Cuando, para la ejecución del delito, la persona responsable se hubiera prevalido de una situación o relación de convivencia o de parentesco.',c:'Cuando el responsable haga uso de armas u otros medios igualmente peligrosos, susceptibles de producir la muerte.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.179.2 CP remite a las circunstancias del art.178.3 CP. Las opciones a, b y c no describen con exactitud esas circunstancias tal como aparecen en el CP.'}},
{n:29, q:'Cuando en el delito de violación del artículo 179.1 del Código Penal concurra alguna de las circunstancias del artículo 180.1 de éste Código se castigará con la pena de prisión de ...', o:{a:'2 a 8 años.',b:'5 a 10 años.',c:'12 a 15 años.',d:'7 a 15 años.'}, correct:'d', why:{d:'Art.179.1 CP en relación con art.180.1 CP: cuando en la violación concurra alguna circunstancia del art.180.1, la pena es de 7 a 15 años de prisión.'}},
{n:30, q:'Cuando en el delito de violación del artículo 179.2 del Código Penal concurra alguna de las circunstancias del artículo 180.1 de éste Código se castigará con la pena de prisión de ...', o:{a:'2 a 8 años.',b:'5 a 10 años.',c:'12 a 15 años.',d:'7 a 15 años.'}, correct:'c', why:{c:'Art.179.2 CP en relación con art.180.1 CP: cuando en la violación agravada concurra además alguna circunstancia del art.180.1, la pena es de 12 a 15 años de prisión.'}},
{n:31, q:'Cuando en el delito de agresiones sexuales del artículo 178.1 del Código Penal concurra alguna de las circunstancias del artículo 180.1 de éste Código se castigará con la pena de prisión de ...', o:{a:'2 a 8 años.',b:'5 a 10 años.',c:'12 a 15 años.',d:'7 a 15 años.'}, correct:'b', why:{b:'Art.178.1 CP en relación con art.180.1 CP: cuando concurra alguna circunstancia agravada, la pena es de 5 a 10 años de prisión.'}},
{n:32, q:'Cuando en el delito de agresiones sexuales del artículo 178.3 del Código Penal concurra alguna de las circunstancias del artículo 180.1 de éste Código se castigará con la pena de prisión de ...', o:{a:'2 a 8 años.',b:'5 a 10 años.',c:'12 a 15 años.',d:'7 a 15 años.'}, correct:'b', why:{b:'Art.178.3 CP en relación con art.180.1 CP: cuando concurra circunstancia agravada, la pena es de 5 a 10 años.'}},
{n:33, q:'Según el artículo 180.1 del Código Penal, indique cuál de las siguientes circunstancias agrava los delitos de agresión sexual y violación.', o:{a:'Cuando los hechos se cometan por la actuación conjunta de dos o más personas.',b:'Cuando el culpable se hubiera prevalido de su condición de autoridad, agente de ésta o funcionario público.',c:'Cuando la víctima sea una persona menor de 16 años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.180.1 CP: todas son circunstancias agravantes: actuación conjunta (1ª), autoridad/funcionario (2ª), víctima menor de 16 años (3ª), entre otras.'}},
{n:34, q:'Según el artículo 180.1 del Código Penal, indique cuál de las siguientes circunstancias agrava los delitos de agresión sexual y violación.', o:{a:'Cuando la víctima sea o haya sido esposa o mujer que esté o haya estado ligada por análoga relación de afectividad aun sin convivencia.',b:'Cuando para la comisión de estos hechos la persona responsable haya anulado la voluntad de la víctima suministrándole fármacos, drogas o cualquier otra sustancia natural o química idónea a tal efecto.',c:'Cuando el responsable haga uso de armas u otros medios igualmente peligrosos, susceptibles de producir la muerte o alguna de las lesiones previstas en los artículos 149 y 150 de este Código.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.180.1 CP: son circunstancias agravantes el uso de fármacos para anular la voluntad (4ª), el uso de armas o medios peligrosos (5ª) y la relación de pareja (6ª).'}},
{n:35, q:'Según el artículo 180.1 del Código Penal, indique cuál de las siguientes circunstancias agrava los delitos de agresión sexual y violación.', o:{a:'Cuando, para la ejecución del delito, la persona responsable se hubiera prevalido de una situación o relación de convivencia o de parentesco o de una relación de superioridad con respecto a la víctima.',b:'Cuando la agresión sexual vaya precedida o acompañada de una violencia de extrema gravedad.',c:'Cuando los actos que revistan un carácter particularmente degradante o vejatorio.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.180.1 CP: son agravantes la situación de convivencia/parentesco/superioridad (7ª), la violencia de extrema gravedad (8ª) y los actos particularmente degradantes (9ª).'}},
{n:36, q:'El Capítulo II del Título VIII, del Libro II del Código Penal, dedicado a las agresiones sexuales a menores de dieciséis años, comprende los artículos...', o:{a:'182 a 183 bis.',b:'181 a 183 bis.',c:'182 a 184 bis.',d:'181 a 184 bis.'}, correct:'b', why:{b:'El Capítulo II del Título VIII dedicado a agresiones sexuales a menores de 16 años comprende los artículos 181 a 183 bis del CP.'}},
{n:37, q:'Según el artículo 181.1 del Código Penal, el que realizare actos de carácter sexual con un menor de 16 años, será castigado con la pena de prisión de...', o:{a:'4 a 8 años.',b:'6 a 12 años.',c:'2 a 6 años.',d:'3 a 5 años.'}, correct:'a', why:{a:'Art.181.1 CP: realizar actos de carácter sexual con un menor de 16 años se castiga con prisión de 4 a 8 años.'}},
{n:38, q:'A los efectos del artículo 181.1 del Código Penal, se consideran incluidos en los actos de carácter sexual...', o:{a:'Los que realice el meno con un tercero.',b:'Los que realice el menor sobre sí mismo a instancia del autor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.181.1 CP: se incluyen los actos que el menor realice con un tercero (a) o sobre sí mismo a instancia del autor (b).'}},
{n:39, q:'Según el artículo 181.2 del Código Penal, los delitos de agresiones sexuales a un menor de 16 años, se castigan con prisión de 5 a 10 años, cuando...', o:{a:'Los actos de contenido sexual se realicen empleando violencia.',b:'Los actos de contenido sexual se cometan por la actuación conjunta de dos o más personas.',c:'El culpable se hubiese prevalido de su condición de autoridad, agente de ésta o funcionario público.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.181.2 CP: agravantes que elevan la pena a 5-10 años: violencia (a), actuación conjunta (b), autoridad/funcionario (c), entre otras.'}},
{n:40, q:'Según el artículo 181.2 del Código Penal, los delitos de agresiones sexuales a un menor de 16 años, se castigan con prisión de 5 a 10 años, cuando...', o:{a:'Los actos de contenido sexual se ejecuten sobre personas que se hallen privadas de sentido.',b:'Se abusare de la situación mental de la víctima.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.181.2 CP: también son agravantes los actos sobre personas privadas de sentido o el abuso de la situación mental de la víctima.'}},
{n:41, q:'Según el artículo 181.2 del Código Penal, los delitos de agresiones sexuales a un menor de 16 años, se castigan con prisión de 5 a 10 años, cuando...', o:{a:'Los actos de contenido sexual se realicen abusando de una situación de superioridad.',b:'Los actos de contenido sexual se cometan abusando de una situación de vulnerabilidad de la víctima.',c:'Los actos se realicen sobre una víctima que tenga anulada por cualquier causa su voluntad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.181.2 CP: superioridad, vulnerabilidad y voluntad anulada son todas agravantes que elevan la pena a 5-10 años.'}},
{n:42, q:'Según el artículo 181.2 del Código Penal, los delitos de agresiones sexuales a un menor de 16 años, se castigan con prisión de 5 a 10 años, cuando concurra alguna de las modalidades descritas...', o:{a:'En el artículo 178.1 y 2 del Código Penal.',b:'En el artículo 178.2 y 3 del Código Penal.',c:'En el artículo 179.1 y 2 del Código Penal.',d:'En el artículo 179.2 y 3 del Código Penal.'}, correct:'b', why:{b:'Art.181.2 CP: se castigan con 5-10 años cuando concurra alguna de las modalidades de los artículos 178.2 y 178.3 del CP.'}},
{n:43, q:'En el delito de realización de actos sexuales con un menor de 16 años, y según el artículo 181.3 del Código Penal, el órgano sentenciador, razonándolo en la sentencia, en atención a la menor entidad del hecho y valorando todas las circunstancias concurrentes, incluyendo las personales del culpable, podrá imponer la pena inferior en grado, excepto cuando....', o:{a:'Medie violencia o intimidación.',b:'Concurra alguna de las circunstancias del artículo 181.5 CP.',c:'Se realice sobre víctima que tenga anulada por cualquier causa su voluntad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.181.3 CP: la atenuación no procede cuando media violencia o intimidación, concurren circunstancias del art.181.5, o la víctima tiene la voluntad anulada.'}},
{n:44, q:'De conformidad con lo dispuesto en el artículo 181.4 del Código Penal, el delito de realización de actos sexuales con un menor de 16 años del artículo 181.1 de este Código, se castiga con una pena de prisión de 8 a 12 años....', o:{a:'Cuando el acto sexual consista en acceso carnal por vía vaginal, anal o bucal.',b:'Cuando la infracción se haya cometido en el seno de una organización o grupo criminal, que se dedique a la realización de tales actividades.',c:'Cuando los actos revistan un carácter particularmente degradante o vejatorio.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.181.4 CP: la pena es de 8-12 años cuando hay acceso carnal, organización criminal o carácter degradante.'}},
{n:45, q:'De conformidad con lo dispuesto en el artículo 181.4 del Código Penal, el delito de realización de actos sexuales con un menor de 16 años del artículo 181.1 de este Código, se castiga con una pena de prisión de 8 a 12 años....', o:{a:'Cuando para la ejecución del delito la persona responsable se hubiera prevalido de una situación o relación de convivencia o parentesco.',b:'Cuando el acto sexual consista en introducción de miembros corporales por vía vaginal o anal.',c:'Cuando el acto sexual consista en introducción de objetos por vía vaginal, anal o bucal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.181.4 CP: también merecen 8-12 años el abuso de convivencia/parentesco y la introducción de miembros u objetos por vías vaginales o anales.'}},
{n:46, q:'De conformidad con lo dispuesto en el artículo 181.4 del Código Penal, el delito de realización de actos sexuales con un menor de 16 años del artículo 181.2 de este Código, se castiga con una pena de prisión de 12 a 15 años, cuando estos actos consistan....', o:{a:'En la introducción de miembros corporales por vía vaginal, anal o bucal.',b:'En la introducción de objetos por vía vaginal, anal o bucal.',c:'En acceso carnal por vía vaginal, anal o bucal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.181.4 in fine CP: cuando los actos del art.181.2 consistan en acceso carnal, introducción de miembros u objetos, la pena es de 12 a 15 años.'}},
{n:47, q:'De conformidad con lo dispuesto en el artículo 181.5 del Código Penal, los delitos de realización de actos sexuales con menores de 16 años, de los apartados 1 a 4 de este artículo, se castigaran con las penas correspondientes en su mitad superior cuando...', o:{a:'Consistan en acceso carnal por vía vaginal, anal o bucal.',b:'La víctima tenga anulada por cualquier causa su voluntad.',c:'Los hechos se cometan por la actuación conjunta de dos o más personas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.181.5 CP: las penas se imponen en su mitad superior por las circunstancias específicas de ese apartado: parentesco/convivencia, autoridad/funcionario, o fármacos/sustancias. Las opciones a, b, c no corresponden exactamente a ese precepto.'}},
{n:48, q:'De conformidad con lo dispuesto en el artículo 181.5 del Código Penal, los delitos de realización de actos sexuales con menores de 16 años, de los apartados 1 a 4 de este artículo, se castigaran con las penas correspondientes en su mitad superior cuando...', o:{a:'El culpable se hubiera prevalido de su condición de autoridad, agente la misma o funcionario público.',b:'La víctima sea o haya sido pareja del autor, aun sin convivencia',c:'Los actos sexuales se lleven a cabo sin el consentimiento de la víctima.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.181.5.b CP: las penas se imponen en su mitad superior cuando el culpable se hubiera prevalido de su condición de autoridad, agente de la misma o funcionario público.'}},
{n:49, q:'De conformidad con lo dispuesto en el artículo 181.5 del Código Penal, los delitos de realización de actos sexuales con menores de 16 años, de los apartados 1 a 4 de este artículo, se castigaran con las penas correspondientes en su mitad superior...', o:{a:'Cuando la agresión sexual vaya precedida o acompañada de una violencia de extrema gravedad o de actos que revistan un carácter particularmente degradante o vejatorio.',b:'Cuando los hechos se cometan contra una persona menor de cuatro años.',c:'Cuando los hechos se cometan contra una persona que se halle en una situación de especial vulnerabilidad por razón de su edad, enfermedad, discapacidad o por cualquier otra circunstancia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.181.5 CP: la mitad superior se aplica en todos esos supuestos.'}},
{n:50, q:'De conformidad con lo dispuesto en el artículo 181.5 del Código Penal, los delitos de realización de actos sexuales con menores de 16 años, de los apartados 1 a 4 de este artículo, se castigaran con las penas correspondientes en su mitad superior...', o:{a:'Cuando, para la ejecución del delito, la persona responsable se hubiera prevalido de una situación o relación de convivencia o de parentesco con respecto a la víctima.',b:'Cuando, para la ejecución del delito, la persona responsable se hubiera prevalido de una relación de superioridad con respecto a la víctima.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.181.5.a CP: la pena se impone en su mitad superior cuando el responsable se prevalió de convivencia/parentesco (a) o de superioridad (b) con la víctima.'}},
{n:51, q:'De conformidad con lo dispuesto en el artículo 181.5 del Código Penal, los delitos de realización de actos sexuales con menores de 16 años, de los apartados 1 a 4 de este artículo, se castigaran con las penas correspondientes en su mitad superior...', o:{a:'Cuando la infracción se haya cometido en el seno de una organización o de un grupo criminal que se dedicare a la realización de tales actividades.',b:'Cuando el responsable haga uso de armas u otros medios igualmente peligrosos, susceptibles de producir la muerte o alguna de las lesiones previstas en los artículos 149 y 150 de este Código, sin perjuicio de lo dispuesto en el artículo 194 bis.',c:'Cuando para la comisión de estos hechos la persona responsable haya anulado la voluntad de la víctima suministrándole fármacos, drogas o cualquier otra sustancia natural o química idónea a tal efecto.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.181.5 CP: organización criminal (c de ese artículo), armas/medios peligrosos (d) y fármacos para anular voluntad (e) también dan lugar a la pena en su mitad superior.'}},
{n:52, q:'En lo que respecta al delito de realizar actos de contenido sexual con menores de 16 años, en caso de que en la descripción de las modalidades típicas previstas en los apartados 1 a 3 del artículo 181 del Código Penal, se hubiera tenido en consideración alguna de las circunstancias del artículo 181.5 de este Código ...', o:{a:'Se aplicará la infracción más gravemente penada en su mitad superior.',b:'Se impondrá la pena superior en uno o dos grados.',c:'Se aplicará la regla del artículo 8.4 de este Código.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.181.5 in fine CP: si la circunstancia del art.181.5 ya fue tenida en cuenta en la modalidad típica, se aplica la infracción más gravemente penada en su mitad superior.'}},
{n:53, q:'Con respecto al delito de actos de contenido sexual realizados con menores de 16 años, en todos los casos previstos en el artículo 181 del Código Penal, cuando el culpable se hubiera prevalido de su condición de autoridad, agente de la misma o funcionario público...', o:{a:'Se impondrá además la pena de inhabilitación absoluta de 6 a 18 años.',b:'Se impondrá además la pena de inhabilitación absoluta de 6 a 12 años.',c:'Se impondrá además la pena de inhabilitación absoluta de 4 a 12 años.',d:'Se impondrá además la pena de inhabilitación absoluta de 8 a 12 años.'}, correct:'b', why:{b:'Art.181.5.b CP: cuando el culpable es autoridad o funcionario, se impone además inhabilitación absoluta de 6 a 12 años.'}},
{n:54, q:'De conformidad con lo dispuesto en el artículo 182 del Código Penal el que, con fines sexuales, haga presenciar a un menor de 16 años actos de carácter sexual, aunque el autor no participe en ellos, será castigado con la pena de prisión...', o:{a:'De 2 a 5 años.',b:'De 1 a 3 años.',c:'De 1 a 6 meses.',d:'De 6 meses a 2 años.'}, correct:'b', why:{b:'Art.182 CP: hacer presenciar a un menor de 16 años actos de carácter sexual se castiga con prisión de 1 a 3 años.'}},
{n:55, q:'De conformidad con lo dispuesto en el artículo 182 del Código Penal, se impondrá la pena de prisión de 1 a 3 años cuando los actos de carácter sexual que se hacen presenciar al menor...', o:{a:'Consistan en acceso carnal por vía vaginal, anal o bucal.',b:'Constituyan un delito contra la libertad sexual.',c:'Los hechos se cometan por la actuación conjunta de dos o más personas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'Art.182 CP: la pena de 1 a 3 años se impone cuando los actos que se hacen presenciar al menor constituyen un delito contra la libertad sexual.'}},
{n:56, q:'Según el artículo 183.1 del Código Penal, constituye delito contactar con un menor de 16 años y proponerle un encuentro con el mismo a fin de cometer cualquier delito de los descritos en los artículos 181 y 189 del Código Penal...', o:{a:'Siempre que el contacto se realice a través de internet, del teléfono o de cualquier otra tecnología de la información y la comunicación.',b:'Siempre que tal propuesta se acompañe de actos materiales encaminados al acercamiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.183.1 CP (child grooming): se requiere tanto el contacto a través de TIC (a) como que la propuesta se acompañe de actos materiales de acercamiento (b).'}},
{n:57, q:'El delito de propuestas sexuales a menores de 16 años, del artículo 183.1 del Código Penal...', o:{a:'Se castiga con las penas de prisión de 1 a 3 años y multa de 12 a 24 meses, sin perjuicio de las correspondientes a los delitos en su caso cometidos.',b:'Se castiga con las penas de prisión de 1 a 3 años o multa de 12 a 24 meses, sin perjuicio de las correspondientes a los delitos en su caso cometidos.',c:'Se castiga con las penas de prisión de 1 a 3 años y multa de 12 a 18 meses, sin perjuicio de las correspondientes a los delitos en su caso cometidos.',d:'Se castiga con las penas de prisión de 1 a 3 años o multa de 12 a 18 meses, sin perjuicio de las correspondientes a los delitos en su caso cometidos.'}, correct:'a', why:{a:'Art.183.1 CP: el child grooming se castiga con prisión de 1 a 3 años Y multa de 12 a 24 meses, sin perjuicio de las penas por delitos cometidos.'}},
{n:58, q:'En el delito de propuestas sexuales a menores de 16 años, del artículo 183.1 del Código Penal, las penas se impondrán en su mitad superior...', o:{a:'Cuando el acercamiento al menor se obtenga mediante coacción.',b:'Cuando el acercamiento al menor se obtenga mediante violencia.',c:'Cuando el acercamiento al menor se obtenga a través de internet, del teléfono o de cualquier otra tecnología de la información y la comunicación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.183.2 CP: las penas se imponen en su mitad superior cuando el acercamiento se obtiene mediante coacción (a), violencia (b) o a través de TIC (c).'}},
{n:59, q:'En el delito de propuestas sexuales a menores de 16 años, del artículo 183.1 del Código Penal, las penas se imponen en su mitad superior...', o:{a:'Cuando el acercamiento al menor se obtenga mediante engaño.',b:'Cuando el acercamiento al menor se obtenga mediante intimidación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.183.2 CP: también se impone la pena en su mitad superior cuando el acercamiento se obtiene mediante engaño (a) o intimidación (b).'}},
{n:60, q:'Según el artículo 183.2 del Código Penal, constituye delito contactar con un menor de 16 años realizando actos dirigidos a embaucarle...', o:{a:'Para concertar un encuentro sexual con él.',b:'Para que le facilite material pornográfico en el que se represente o aparezca un menor.',c:'Para que le facilite acceso a su intimidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.183.2 CP: es delito embaucar a un menor de 16 años para concertar encuentro sexual (a), obtener material pornográfico con menores (b) o acceder a su intimidad (c).'}},
{n:61, q:'El delito del artículo 183.2 del Código Penal requiere que...', o:{a:'El contacto con el menor se lleve a cabo a través de internet.',b:'El contacto con el menor se lleve a cabo a través del teléfono.',c:'El contacto con el menor se lleve a cabo utilizando cualquier tecnología de la información y la comunicación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.183.2 CP: el delito puede cometerse a través de internet (a), teléfono (b) o cualquier otra TIC (c).'}},
{n:62, q:'El delito del artículo 183.2 del Código Penal se castiga con...', o:{a:'Prisión de 2 a 5 años.',b:'Prisión de 2 a 5 años o multa de 12 a 24 meses.',c:'Prisión de 6 meses a 2 años.',d:'Prisión de 6 meses a 2 años o multa de 12 a 24 meses.'}, correct:'a', why:{a:'Art.183.2 CP: el embaucamiento de menores a través de TIC se castiga con prisión de 2 a 5 años.'}},
{n:63, q:'El libre consentimiento del menor de 16 años excluirá la responsabilidad penal. Con relación a esta afirmación, indique la respuesta correcta.', o:{a:'Requiere que el autor de los hechos sea también menor de 16 años.',b:'No es aplicación cuando concurra alguna de las circunstancias del apartado 5 del artículo 181 del Código Penal.',c:'Está recogida en el artículo 183.2 del Código Penal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.183 bis CP: el libre consentimiento del menor de 16 años puede excluir la responsabilidad, pero no cuando concurran las circunstancias del art.181.5 CP.'}},
{n:64, q:'Según el artículo 183 bis del Código Penal, el libre consentimiento del menor de 16 años excluirá la responsabilidad penal...', o:{a:'Cuando el autor de los hechos sea una persona próxima al menor por edad y grado de desarrollo o madurez física y psicológica.',b:'Cuando los hechos se hayan llevado a cabo a través de internet, del teléfono o de cualquier otra tecnología de la información y la comunicación.',c:'Cuando los actos no consistan en acceso carnal por vía vaginal, anal o bucal, ni en la introducción de objetos o miembros corporales por las dos primeras vías.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.183 bis CP: el libre consentimiento del menor de 16 años excluye la responsabilidad cuando el autor es una persona próxima al menor por edad y grado de madurez.'}},
{n:65, q:'Los delitos de acoso sexual están tipificados en...', o:{a:'El artículo 183 del Código Penal.',b:'El artículo 184 del Código Penal.',c:'El artículo 185 del Código Penal.',d:'El artículo 183 bis del Código Penal.'}, correct:'b', why:{b:'Los delitos de acoso sexual están tipificados en el artículo 184 del CP (Capítulo III del Título VIII).'}},
{n:66, q:'Según el artículo 184.2 del Código Penal, si el culpable de un delito de acoso sexual hubiese cometido el hecho prevaliéndose de una situación de superioridad laboral, docente o jerárquica...', o:{a:'Se le impondrán las penas de prisión de 6 meses a 2 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 18 a 24 meses.',b:'Se le impondrán las penas de prisión de 1 a 2 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 12 a 24 meses.',c:'Se le impondrán las penas de prisión de 1 a 3 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 12 a 24 meses.',d:'Se le impondrán las penas de prisión de 1 a 2 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 18 a 24 meses.'}, correct:'d', why:{d:'Art.184.2 CP: cuando media superioridad laboral/docente/jerárquica, la pena es prisión de 1 a 2 años e inhabilitación especial de 18 a 24 meses.'}},
{n:67, q:'Según el artículo 184.2 del Código Penal, si el culpable de un delito de un delito de acoso sexual hubiese cometido el hecho con el anuncio expreso o tácito de causar a la víctima un mal relacionado con las legítimas expectativas que aquella pudiera tener en el ámbito de una relación laboral, docente o jerárquica...', o:{a:'Se le impondrán las penas de prisión de 1 a 3 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 12 a 24 meses.',b:'Se le impondrán las penas de prisión de 1 a 2 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 12 a 24 meses.',c:'Se le impondrán las penas de prisión de 6 meses a 2 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 18 a 24 meses.',d:'Se le impondrán las penas de prisión de 1 a 2 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 12 a 24 meses.'}, correct:'d', why:{d:'Art.184.2 CP: el anuncio de causar un mal en el ámbito laboral/docente/jerárquico se castiga con prisión de 1 a 2 años e inhabilitación de 12 a 24 meses.'}},
{n:68, q:'Según el artículo 184.2 del Código Penal, si el culpable de un delito de acoso sexual hubiese cometido el hecho sobre una persona sujeta a su guarda o custodia...', o:{a:'Se le impondrán las penas de prisión de 1 a 2 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 12 a 24 meses.',b:'Se le impondrán las penas de prisión de 1 a 3 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 12 a 24 meses.',c:'Se le impondrán las penas de prisión de 1 a 2 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 18 a 24 meses.',d:'Se le impondrán las penas de prisión de 6 meses a 2 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad, 18 a 24 meses.'}, correct:'c', why:{c:'Art.184.2 CP: cuando el acoso es sobre persona bajo guarda o custodia del autor, la pena es prisión de 1 a 2 años e inhabilitación de 18 a 24 meses.'}},
{n:69, q:'Respecto del delito de acoso sexual del artículo 184 del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castiga el hecho de solicitar favores de naturaleza sexual para el solicitante o para un tercero.',b:'La pena para el tipo básico es la de prisión de 6 a 12 meses y multa de 10 a 15 meses, e inhabilitación especial para el ejercicio de profesión, oficio o actividad de 12 a 24 meses.',c:'Para que exista delito, la solicitud debe hacerse en el ámbito de una relación laboral, docente o de prestación de servicios, o análoga, continuada o habitual.',d:'Para que exista delito, la solicitud debe provocar en la víctima una situación objetiva y gravemente intimidatoria, hostil o humillante.'}, correct:'b', why:{b:'La opción b es incorrecta: la pena del tipo básico del art.184.1 CP no es prisión de 6 a 12 meses sino multa de 6 a 12 meses e inhabilitación especial de 12 a 24 meses.'}},
{n:70, q:'Según el artículo 184.3 del Código Penal, el acoso sexual será castigado con las penas de prisión de 1 a 2 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de 18 a 24 meses, cuando...', o:{a:'Se cometa por dos o más personas.',b:'Se cometa en centros de protección o reforma de menores.',c:'Se cometa a través de internet, del teléfono o de cualquier otra tecnología de la información y la comunicación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.184.3 CP: la pena agravada de 1-2 años e inhabilitación 18-24 meses se aplica cuando el acoso es por dos o más personas (a), en centros de menores (b) o a través de TIC (c).'}},
{n:71, q:'Según el artículo 184.3 del Código Penal, el acoso sexual será castigado con las penas de prisión de 1 a 2 años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de 18 a 24 meses, cuando...', o:{a:'Se lleve a cabo en un centro de internamiento de personas extranjeras.',b:'Se lleve a cabo empleando violencia o intimidación.',c:'Se lleve a cabo empleando armas u objetos peligrosos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.184.3 CP: también son circunstancias agravadas el internamiento de extranjeros (a), violencia o intimidación (b) y armas u objetos peligrosos (c).'}},
{n:72, q:'Según el artículo 184.4 del Código Penal, en los delitos de acoso sexual tipificados en los apartados 1,2 y 3 de este artículo, se impondrá la pena en su mitad superior cuando...', o:{a:'Cuando el delito se lleve a cabo en un centro de detención, custodia o acogida.',b:'Cuando la víctima se halle en una situación de especial vulnerabilidad por razón de su edad, enfermedad o discapacidad.',c:'Cuando el delito se lleve a cabo empleando violencia o intimidación.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'b', why:{b:'Art.184.4 CP: la pena se impone en su mitad superior cuando la víctima se halla en situación de especial vulnerabilidad por edad, enfermedad o discapacidad.'}},
{n:73, q:'Según el artículo 184.5 del Código Penal, cuando el delito de acoso sexual sea cometido por una persona jurídica ...', o:{a:'Se le impondrá la pena de multa de 6 meses a 2 años.',b:'Los Jueces o Tribunales podrán imponerle las penas recogidas en las letras b) a j) del apartado 5, del artículo 33 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.184.5 CP: cuando el acoso sexual es cometido por persona jurídica, se impone multa de 6 meses a 2 años (a) y las penas del art.33.7.b a j (b).'}},
{n:74, q:'Los delitos de exhibicionismo y provocación sexual están tipificados en...', o:{a:'Los artículos 183 y 184 del Código Penal.',b:'Los artículos 185 y 186 del Código Penal.',c:'Los artículos 186 y 187 del Código Penal.',d:'Los artículos 185, 186 y 187 bis del Código Penal.'}, correct:'b', why:{b:'Los delitos de exhibicionismo y provocación sexual están tipificados en los artículos 185 y 186 del CP (Capítulo IV del Título VIII).'}},
{n:75, q:'Con respecto al delito de exhibicionismo del artículo 185 del Código Penal, indique la respuesta incorrecta.', o:{a:'La conducta que se castiga es la de ejecutar o hacer ejecutar a otra persona actos de exhibición obscena.',b:'Para que exista delito, los actos de exhibición obscena deben realizarse ante menores de edad o personas con discapacidad necesitadas de especial protección.',c:'Cuando los actos de exhibición obscena se llevan a cabo ante personas mayores de edad, se impone la pena inferior en grado.',d:'Este delito se castiga con pena de prisión de 6 meses a 1 año o multa de 12 a 24 meses.'}, correct:'c', why:{c:'La opción c es incorrecta: cuando los actos de exhibicionismo se realizan ante personas mayores de edad capaces, la conducta es atípica (no hay delito ni pena). No se aplica una pena inferior en grado.'}},
{n:76, q:'El exhibicionismo o provocación sexual realizado ante mayores de edad:', o:{a:'Constituye delito leve tipificado en el artículo 185.2 del Código Penal.',b:'Constituye infracción a la Ley Orgánica 4/2015 sobre Protección de la Seguridad Ciudadana.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El exhibicionismo ante mayores de edad capaces no es delito penal sino infracción administrativa tipificada en la LO 4/2015 de Protección de la Seguridad Ciudadana.'}},
{n:77, q:'Con respecto al delito de difusión de material pornográfico tipificado en el artículo 186 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto pasivo de este delito solo pueden serlo los menores de edad, incapaces o las personas especialmente vulnerables que convivan con el autor.',b:'Se castiga a quienes, por cualquier medio directo o indirecto, vendieren, difundieren o exhibieren material pornográfico.',c:'Este delito se castiga con la pena de prisión de 6 meses a 1 año y multa de 12 a 24 meses.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'La opción a es incorrecta: el art.186 CP se refiere a los menores de edad e incapaces como sujetos pasivos, sin incluir la exigencia de convivencia con el autor para las personas especialmente vulnerables.'}},
{n:78, q:'El delito de difusión de material pornográfico tipificado en el artículo 186 del Código Penal se castiga con las penas de....', o:{a:'Prisión de 6 meses a 1 año o multa de 12 a 24 meses.',b:'Prisión de 1 a 3 años o multa de 12 a 24 meses.',c:'Prisión de 6 meses a 1 año o multa de 12 a 18 meses.',d:'Prisión de 1 a 2 años o multa de 12 a 18 meses.'}, correct:'a', why:{a:'Art.186 CP: la difusión de material pornográfico entre menores se castiga con prisión de 6 meses a 1 año o multa de 12 a 24 meses.'}},
{n:79, q:'Los delitos relativos a la prostitución y a la explotación sexual y corrupción de menores están tipificados en...', o:{a:'Los artículos 188 a 189 ter del Código Penal.',b:'Los artículos 187 a 189 bis del Código Penal.',c:'Los artículos 187 a 189 ter del Código Penal.',d:'Los artículos 188 a 189 bis del Código Penal.'}, correct:'c', why:{c:'Los delitos de prostitución, explotación sexual y corrupción de menores están en los artículos 187 a 189 ter del CP (Capítulo V del Título VIII).'}},
{n:80, q:'Los delitos relativos a la prostitución del artículo 187.1 del Código Penal, requieren de...', o:{a:'El empleo de violencia.',b:'El empleo de intimidación.',c:'Engaño.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.187.1 CP: los delitos de prostitución requieren el empleo de violencia (a), intimidación (b) o engaño (c), entre otros medios.'}},
{n:81, q:'Es requisito de los delitos relativos a la prostitución del artículo 187.1 del Código Penal, ...', o:{a:'El abuso de una situación de superioridad.',b:'El abuso de una situación de necesidad de la víctima.',c:'El abuso de una situación de vulnerabilidad de la víctima.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.187.1 CP: también son requisitos el abuso de superioridad (a), necesidad (b) o vulnerabilidad (c) de la víctima.'}},
{n:82, q:'En los delitos relativos a la prostitución del artículo 187.1 del Código Penal,...', o:{a:'Se castiga al que, para su propio uso, posea material pornográfico en cuya elaboración se hubieran utilizado menores de edad o incapaces, o lo poseyere para estos fines, aunque el material tuviere su origen en el extranjero o fuere desconocido.',b:'Se castiga al que, empleando violencia, intimidación o engaño, o abusando de una situación de superioridad o de necesidad o vulnerabilidad de la víctima, determine a una persona mayor de edad a ejercer la prostitución o a mantenerse en ella.',c:'Se castiga al que solicite, acepte u obtenga a cambio de una remuneración o promesa, una relación sexual con persona menor de edad o incapaz.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.187.1 CP: se castiga al que mediante violencia, intimidación, engaño o abuso de situación determine a una persona mayor de edad a ejercer o mantenerse en la prostitución.'}},
{n:83, q:'Los delitos relativos a la prostitución del artículo 187.1 del Código Penal, se castigan con las penas de ...', o:{a:'Prisión de 2 a 4 años y multa de 12 a 24 meses.',b:'Prisión de 2 a 5 años y multa de 12 a 24 meses.',c:'Prisión de 2 a 4 años y multa de 12 a 18 meses.',d:'Prisión de 2 a 5 años y multa de 12 a 18 meses.'}, correct:'b', why:{b:'Art.187.1 CP: los delitos de prostitución forzada se castigan con prisión de 2 a 5 años y multa de 12 a 24 meses.'}},
{n:84, q:'En el segundo párrafo del artículo 187.1 del Código Penal, se castiga...', o:{a:'A quien se lucre explotando la prostitución de otra persona, aun con el consentimiento de la misma.',b:'Al que asistiere a sabiendas a espectáculos exhibicionistas o pornográficos en los que participen menores de edad o personas con discapacidad necesitadas de especial protección',c:'Al que para su propio uso adquiera o posea pornografía infantil o en cuya elaboración se hubieran utilizado personas con discapacidad necesitadas de especial protección.',d:'Al que solicite, acepte u obtenga, a cambio de una remuneración o promesa, una relación sexual con persona menor de edad, o persona con discapacidad necesitada de especial protección.'}, correct:'a', why:{a:'Art.187.1 párr.2 CP: también se castiga al que se lucre explotando la prostitución de otra persona, aunque haya consentimiento.'}},
{n:85, q:'Lucrarse explotando la prostitución de otra persona es un delito contenido en el segundo párrafo del artículo 187.1 del Código Penal, que se castiga con las penas de...', o:{a:'Prisión de 2 a 4 años y multa de 12 a 24 meses.',b:'Prisión de 2 a 5 años y multa de 12 a 24 meses.',c:'Prisión de 2 a 4 años y multa de 12 a 18 meses.',d:'Prisión de 2 a 5 años y multa de 12 a 18 meses.'}, correct:'b', why:{b:'Art.187.1 párr.2 CP: lucrarse explotando la prostitución ajena se castiga también con prisión de 2 a 5 años y multa de 12 a 24 meses.'}},
{n:86, q:'El artículo 187.1 del Código Penal considera que existe explotación lucrativa de la prostitución ajena, cuando:', o:{a:'La víctima fuere menor de 16 años o persona con discapacidad necesitada de especial protección.',b:'La víctima se encuentre en una situación de vulnerabilidad personal o económica.',c:'El culpable se haya prevalido de su condición de autoridad, agente de la misma o funcionario público.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.187.1 CP: la explotación lucrativa concurre en todos esos supuestos (víctima menor/discapacitada, vulnerabilidad personal/económica, autoridad/funcionario).'}},
{n:87, q:'El artículo 187.1 del Código Penal considera que existe explotación lucrativa de la prostitución ajena, cuando:', o:{a:'Se impongan a la persona que ejerce la prostitución condiciones gravosas, desproporcionadas o abusivas.',b:'El culpable hubiese puesto en peligro, de forma dolosa o por imprudencia grave, la vida o salud de la víctima.',c:'El culpable perteneciere a una organización o grupo criminal que se dedicare a la realización de tales actividades.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.187.1 CP: también es explotación lucrativa cuando hay condiciones abusivas (a), peligro para la vida/salud (b) u organización criminal (c).'}},
{n:88, q:'Según el artículo 187.2 del Código Penal, los delitos de explotación de la prostitución ajena, tipificados en el artículo 187.1 del Código Penal, se castigan con las penas respectivamente previstas en su mitad superior, cuando...', o:{a:'El culpable hubiese puesto en peligro, de forma dolosa o por imprudencia grave, la vida o salud de la víctima.',b:'El culpable perteneciere a una organización o grupo criminal que se dedicare a la realización de tales actividades.',c:'El culpable se haya prevalido de su condición de autoridad, agente de la misma o funcionario público.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.187.2 CP: las penas se imponen en su mitad superior en los tres supuestos mencionados.'}},
{n:89, q:'Dispone el artículo 187 del Código Penal...', o:{a:'Que cuando el culpable de alguno de los delitos de explotación de la prostitución ajena previstos en este artículo se hubiera prevalido de su condición de autoridad o funcionario público se le impondrá, además, la pena de inhabilitación absoluta de 10 a 15 años.',b:'Que las penas señaladas en los respectivos casos sin perjuicio de las que correspondan por las agresiones o abusos sexuales cometidos sobre la persona prostituida.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.187.3 CP: cuando el culpable es autoridad o funcionario se añade inhabilitación absoluta de 10 a 15 años (a), y las penas son sin perjuicio de las que correspondan por agresiones sexuales (b).'}},
{n:90, q:'Con respecto a los delitos relativos a la prostitución tipificados en el artículo 188.1 del Código Penal, indique la respuesta correcta...', o:{a:'Se castiga la inducción, promoción, favorecimiento o facilitación de la prostitución.',b:'Sujeto pasivo de estos delitos solo pueden serlo los menores de edad o las personas con discapacidad necesitadas de especial protección.',c:'Se castiga el hecho de lucrarse con la prostitución, o explotar de algún otro modo a un menor o persona con discapacidad necesitada de especial protección.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.188.1 CP: se castiga la inducción/favorecimiento de la prostitución de menores o discapacitados (a y c), siendo estos el sujeto pasivo (b).'}},
{n:91, q:'Con respecto a los delitos relativos a la prostitución tipificados en el artículo 188.1 del Código Penal, indique la respuesta incorrecta...', o:{a:'Cuando la víctima fuere menor de 16 años se impondrán las penas superiores en grado a las previstas para el tipo básico.',b:'Si los hechos se cometen con violencia o intimidación, además de las penas de multa previstas, se impondrá la pena de prisión de 5 a 10 años, si la víctima es menor de 16 años.',c:'Si los hechos se cometen con violencia o intimidación, además de las penas de multa previstas, se impondrá la pena de prisión de 4 a 6 años, si la víctima es mayor de 16 años.',d:'Se impondrán las penas superiores en grado a las respectivamente previstas, cuando la víctima sea especialmente vulnerable por razón de su edad, enfermedad, discapacidad o situación.'}, correct:'b', why:{b:'La opción b es incorrecta porque el art.188 CP no establece exactamente esa combinación de penas para violencia con víctima menor de 16 años.'}},
{n:92, q:'Según el artículo 188.3 del Código Penal, los autores de estos delitos serán castigados con las penas superiores en grado a las respectivamente previstas en los apartados 1 y 2 de este artículo...', o:{a:'Cuando hubiere mediado precio, recompensa o promesa.',b:'Cuando los hechos se cometan por la actuación conjunta de dos o más personas.',c:'Cuando la víctima sea o haya sido esposa o mujer que esté o haya estado ligada al autor por análoga relación de afectividad, aún sin convivencia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.188.3 CP: las penas son superiores en grado por precio/recompensa (a), actuación conjunta (b) o relación de pareja (c).'}},
{n:93, q:'Según el artículo 188.3 del Código Penal, los autores de estos delitos serán castigados con las penas superiores en grado a las respectivamente previstas en los apartados 1 y 2 de este artículo...', o:{a:'Cuando el responsable haga uso de armas u otros medios igualmente peligrosos.',b:'Cuando para la comisión de estos hechos la persona responsable haya anulado la voluntad de la víctima suministrándole fármacos, drogas o cualquier otra sustancia natural o química idónea a tal efecto.',c:'Cuando se haya empleado violencia o intimidación.',d:'Cuando para la ejecución del delito el responsable se hubiese prevalido de una situación de convivencia.',}, correct:'d', why:{d:'Art.188.3 CP también agrava cuando se prevale de situación de convivencia. El uso de armas, fármacos y violencia se recogen en otros apartados.'}},
{n:94, q:'Según el artículo 188.3 del Código Penal, los autores de estos delitos serán castigados con las penas superiores en grado a las respectivamente previstas en los apartados 1 y 2 de este artículo...', o:{a:'Cuando para la ejecución del delito, el responsable se hubiera prevalido de su condición de autoridad, agente de ésta o funcionario público.',b:'Cuando el culpable hubiere puesto en peligro, de forma dolosa o por imprudencia grave, la vida o salud de la víctima.',c:'Cuando el culpable perteneciere a una organización o asociación, incluso de carácter transitorio, que se dedicare a la realización de tales actividades.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.188.3 CP: autoridad/funcionario (a), peligro para vida/salud (b) y organización criminal (c) también dan lugar a penas superiores en grado.'}},
{n:95, q:'Según el artículo 188.3 del Código Penal, los autores de estos delitos serán castigados con las penas superiores en grado a las respectivamente previstas en los apartados 1 y 2 de este artículo...', o:{a:'Cuando para la ejecución del delito, el responsable se hubiera prevalido de una situación de parentesco por ser ascendiente o hermano, o afines con la víctima.',b:'Cuando se haya llevado a cabo mediante violencia, intimidación o engaño.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.188.3 CP: el parentesco ascendente/hermano (a) y la violencia/intimidación/engaño (b) son también agravantes que elevan la pena en grado.'}},
{n:96, q:'Con respecto al delito del artículo 188.4 del Código Penal, indique la respuesta correcta.', o:{a:'La conducta punible consiste en inducir, promover, favorecer o facilitar la prostitución de una persona mayor de edad.',b:'La conducta punible consiste en solicitar, aceptar u obtener una relación sexual con persona menor de edad, a cambio de una remuneración o promesa.',c:'La conducta punible consiste en captar o utilizar a menores de edad o personas con discapacidad con fines o en espectáculos exhibicionistas o pornográficos.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.188.4 CP: se castiga al que solicite, acepte u obtenga una relación sexual con persona menor de edad a cambio de remuneración o promesa.'}},
{n:97, q:'Con respecto a los delitos relativos a la prostitución tipificados en el artículo 188.4 del Código Penal, indique la respuesta que no es correcta:', o:{a:'Sujetos pasivos de este delito solo pueden serlo los menores de edad o personas con discapacidad necesitadas de especial protección.',b:'Se castiga el hecho de solicitar, aceptar u obtener una relación sexual a cambio de una remuneración o promesa.',c:'La pena a imponer por este delito es la prisión de 1 a 4 años.',d:'La pena se impondrá en su mitad superior cuando el menor no hubiera cumplido los 16 años de edad.'}, correct:'c', why:{c:'La opción c es incorrecta: la pena del art.188.4 CP no es de 1 a 4 años para todos los supuestos; depende de la edad del menor.'}},
{n:98, q:'Los delitos relativos a la prostitución del artículo 188.4 del Código Penal, se castigan...', o:{a:'Con la pena de 1 a 4 años de prisión, cuando el menor hubiera cumplido los 16 años de edad.',b:'Con la pena 2 a 6 años de prisión, cuando el menor no hubiera cumplido los 16 años de edad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.188.4 CP: la pena es de 1-4 años cuando el menor tiene 16-17 años (a), y de 2-6 años cuando es menor de 16 (b).'}},
{n:99, q:'En el delito de corrupción de menores del artículo 189.1 del Código Penal, se castiga:', o:{a:'Captar o utilizar a menores de edad o personas con discapacidad necesitadas de especial protección, con fines o en espectáculos exhibicionistas o pornográficos.',b:'Captar o utilizar a menores de edad o personas con discapacidad necesitadas de especial protección, para elaborar cualquier clase de material pornográfico.',c:'Financiar o lucrarse con motivo de alguna de las actividades de captación o utilización de menores o personas con discapacidad necesitadas de especial protección, en espectáculos exhibicionistas o pornográficos, o con motivo de cualquier tipo de material pornográfico que se elabore con éstos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.1 CP: se castigan todas esas conductas: captación para espectáculos (a), elaboración de pornografía (b) y lucrarse de esas actividades (c).'}},
{n:100, q:'En el delito de corrupción de menores del artículo 189.1 del Código Penal, se castiga:', o:{a:'Producir pornografía infantil.',b:'Vender o distribuir pornografía infantil.',c:'Exhibir pornografía infantil',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.1 CP: producir (a), vender/distribuir (b) y exhibir (c) pornografía infantil son todas conductas castigadas.'}},
{n:101, q:'En el delito de corrupción de menores del artículo 189.1 del Código Penal, se castiga:', o:{a:'Asistir, a sabiendas, a espectáculos exhibicionistas o pornográficos en los que participen menores de edad.',b:'Elaboración de pornografía utilizando personas con discapacidad necesitadas de especial protección.',c:'Adquirir para uso propio pornografía en cuya elaboración se hayan utilizado personas con discapacidad necesitadas de especial protección.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.1 CP: asistir a espectáculos con menores (a), elaborar pornografía con discapacitados (b) y adquirir para uso propio (c) son todas conductas punibles.'}},
{n:102, q:'En el delito de corrupción de menores del artículo 189.1 del Código Penal, se castiga:', o:{a:'Producir, vender, distribuir, exhibir, ofrecer o facilitar la producción, venta, difusión o exhibición por cualquier medio de pornografía infantil o en cuya elaboración hayan sido utilizadas personas con discapacidad necesitadas de especial protección.',b:'Solicitar, aceptar u obtener, a cambio de una remuneración o promesa, una relación sexual con una persona menor de edad o una persona con discapacidad necesitada de especial protección.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.189.1.a CP: producir, vender, distribuir, exhibir o facilitar pornografía infantil o con discapacitados es conducta punible. La opción b corresponde al art.188.4 CP, no al 189.1.'}},
{n:103, q:'Según el artículo 189 del Código Penal, se considera pornografía infantil o en cuya elaboración hayan sido utilizadas personas con discapacidad necesitadas de especial protección...', o:{a:'Todo material que represente de manera visual a un menor participando en una conducta sexualmente explícita real.',b:'Todo material que represente de manera visual a una persona que parezca ser un menor participando en una conducta sexualmente explícita real.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.189.7 CP: es pornografía infantil tanto el material con menores reales (a) como el que represente a personas que parezcan menores (b).'}},
{n:104, q:'Según el artículo 189 del Código Penal, se considera pornografía infantil o en cuya elaboración hayan sido utilizadas personas con discapacidad necesitadas de especial protección...', o:{a:'Todo material que represente de manera visual a un menor participando en una conducta sexualmente explícita simulada.',b:'Todo material que represente de manera visual a una persona con discapacidad participando en una conducta sexualmente explícita simulada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.189.7 CP: también es pornografía el material con conductas simuladas, tanto de menores (a) como de personas con discapacidad (b).'}},
{n:105, q:'Según el artículo 189 del Código Penal, se considera pornografía infantil o en cuya elaboración hayan sido utilizadas personas con discapacidad necesitadas de especial protección...', o:{a:'Toda representación de los órganos sexuales de una persona con discapacidad necesitada de especial protección con fines principalmente sexuales.',b:'Imágenes realistas de un menor participando en una conducta sexualmente explícita.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.189.7 CP: también es pornografía la representación de órganos sexuales de personas con discapacidad (a) e imágenes realistas de menores (b).'}},
{n:106, q:'Según el artículo 189 del Código Penal, se considera pornografía infantil o en cuya elaboración hayan sido utilizadas personas con discapacidad necesitadas de especial protección...', o:{a:'Cualquier representación de los órganos sexuales de una persona que parezca ser una persona con discapacidad necesitada de especial protección.',b:'Imágenes realistas de una persona con discapacidad necesitada de especial protección con fines principalmente sexuales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.189.7 CP: la definición abarca representaciones de órganos sexuales de quien parezca tener discapacidad (a) e imágenes realistas con fines sexuales (b).'}},
{n:107, q:'El artículo 189 del Código Penal considera pornografía infantil o en cuya elaboración hayan sido utilizadas personas con discapacidad necesitadas de especial protección:', o:{a:'Todo material que represente de forma visual a una persona que parezca ser un menor, participando en una conducta sexualmente explícita, real o simulada, o cualquier representación de los órganos sexuales de una persona que parezca ser un menor con fines principalmente sexuales, salvo que la persona que parezca ser el menor tenga en realidad 18 años o más, en el momento de obtenerse las imágenes.',b:'Toda representación de los órganos sexuales de un menor o persona con discapacidad con fines principalmente sexuales.',c:'Todo material que represente de forma visual a una persona que parezca ser un menor con fines principalmente sexuales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.7 CP: la definición de pornografía infantil abarca todas las modalidades descritas.'}},
{n:108, q:'Los delitos de corrupción de menores del artículo 189.1 del Código Penal se castigan con pena de prisión de 5 a 9 años:', o:{a:'Cuando los hechos revistan un carácter particularmente degradante o vejatorio.',b:'Cuando se utilice a niños menores de 16 años.',c:'Cuando el culpable perteneciere a una organización o asociación, incluso de carácter transitorio, que se dedicare a tales actividades.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.2 CP: carácter degradante (a), víctima menor de 16 años (b) y organización criminal (c) son agravantes que elevan la pena a 5-9 años.'}},
{n:109, q:'Los delitos de corrupción de menores del artículo 189.1 del Código Penal se castigan con pena de prisión de 5 a 9 años:', o:{a:'Cuando el material pornográfico fuere de notoria importancia.',b:'Cuando en los hechos participaren dos o más personas.',c:'Cuando consista en acceso carnal por vía vaginal, anal o bucal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.2 CP: material de notoria importancia (a), participación de dos o más (b) y acceso carnal (c) son también agravantes con pena de 5-9 años.'}},
{n:110, q:'Los delitos de corrupción de menores del artículo 189.1 del Código Penal se castigan con pena de prisión de 5 a 9 años:', o:{a:'Cuando la víctima tenga anulada su voluntad por cualquier causa.',b:'Cuando se utilice a personas menores de edad que se hallen en una situación de especial vulnerabilidad por razón de enfermedad, discapacidad o por cualquier otra circunstancia.',c:'Cuando el responsable haga uso de armas u otros instrumentos igualmente peligrosos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.2 CP: voluntad anulada (a), especial vulnerabilidad (b) y armas (c) son agravantes adicionales.'}},
{n:111, q:'Los delitos de corrupción de menores del artículo 189.1 del Código Penal se castigan con pena de prisión de 5 a 9 años:', o:{a:'Cuando el culpable se hubiera prevalido de su condición de autoridad, agente de ésta o funcionario público.',b:'Cuando la víctima sea o haya sido pareja del autor, aun sin convivencia.',c:'Cuando se emplee violencia física o sexual para la obtención del material pornográfico, o se representen escenas de violencia física o sexual.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.2 CP: autoridad/funcionario (a), pareja (b) y violencia física o sexual en el material (c) son también circunstancias agravantes.'}},
{n:112, q:'Los delitos de corrupción de menores del artículo 189.1 del Código Penal se castigan con pena de prisión de 5 a 9 años:', o:{a:'Cuando el culpable hubiere puesto en peligro, de forma dolosa o por imprudencia grave, la vida o salud de la víctima.',b:'Cuando el culpable sea ascendiente, tutor, curador guardador, maestro o persona encargada de la víctima.',c:'Cuando la víctima conviva con el autor.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.2 CP: peligro para vida/salud (a) y relación de ascendencia/tutela/guarda (b y c) son también agravantes.'}},
{n:113, q:'Los delitos de corrupción de menores del artículo 189.1 del Código Penal se castigan con pena de prisión de 5 a 9 años:', o:{a:'Cuando concurra la agravante de alevosía.',b:'Cuando concurra la agravante de reincidencia.',c:'Cuando concurra la agravante de abuso de confianza.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.2 CP: la alevosía (a), reincidencia (b) y abuso de confianza (c) son también circunstancias agravantes para este delito.'}},
{n:114, q:'En el artículo 189 del Código Penal se castiga como delito:', o:{a:'Asistir, a sabiendas, o por negligencia inexcusable, a espectáculos exhibicionistas o pornográficos en los que participen menores de edad o personas con discapacidad necesitadas de especial protección.',b:'Acceder a sabiendas a cualquier tipo de pornografía, a través de cualquier tecnología de la información y la comunicación, en la que aparezcan prácticas sexuales violentas o intimidatorias.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.189.4 CP: asistir a espectáculos pornográficos con menores (a) y acceder a pornografía violenta online (b) son conductas castigadas.'}},
{n:115, q:'Poseer, para uso propio, material pornográfico en cuya elaboración se hubiesen utilizado menores de edad o persona con discapacidad necesitada de especial protección...', o:{a:'Constituye delito del artículo 189.5 del Código Penal.',b:'Se castiga con las penas de prisión de 6 meses a 1 año de prisión, o con multa de 6 meses a 2 años.',c:'Es un delito que solo puede perseguirse mediante denuncia de la persona agraviada o su representante legal, o mediante querella del Ministerio Fiscal.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'d', why:{d:'La posesión para uso propio de pornografía infantil es delito del art.189.5 CP pero la pena y la persecución descritas en b y c no son exactas, por lo que ninguna opción es completamente correcta.'}},
{n:116, q:'Acceder a sabiendas a pornografía infantil, o en cuya elaboración se hubieran utilizado personas con discapacidad necesitadas de especial protección...', o:{a:'Constituye delito del artículo 189.5 del Código Penal.',b:'Se castiga con las penas de 3 meses a 1 año de prisión, o con multa de 6 meses a 2 años.',c:'Es un delito que solo puede cometerse a través de las tecnologías de la información y la comunicación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.5 CP: acceder a pornografía infantil (a), con esa pena (b) y cometido a través de TIC (c) son todas correctas.'}},
{n:117, q:'En el art.189.6 del Código Penal se castiga al que, teniendo bajo su potestad, tutela, guarda o acogimiento un menor de edad o persona con discapacidad necesitada de especial protección, y con noticia de la prostitución o corrupción de éste, no haga lo posible para impedir su continuación en tal estado. De acuerdo con este enunciado, indique cuál de las siguientes afirmaciones es correcta.', o:{a:'Este precepto también castiga a quien realizare actos de contenido sexual con un menor de 16 años o persona con discapacidad necesitada de especial protección.',b:'Este precepto también castiga al que no acudiera a la autoridad competente para el mismo fin, si carece de medios para su custodia.',c:'Este delito se castiga con las penas de prisión de 3 a 6 meses y multa de 6 a 12 meses.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.6 CP: también castiga a quien no acude a la autoridad (b) y la pena es de 3-6 meses e multa de 6-12 meses (c). La conducta del tutor/guardador que conoce la corrupción es el tipo principal (a).'}},
{n:118, q:'En el artículo 189.7 del Código Penal se dispone que el Ministerio Fiscal promoverá las acciones pertinentes para privar de la patria potestad, tutela, curatela, guarda o acogimiento familiar a quien incurra en alguna de las conductas previstas...', o:{a:'En el artículo 189.5 del Código Penal.',b:'En el artículo 189.6 del Código Penal.',c:'En el artículo 189, apartado 8, del Código penal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El art.189.7 CP no contiene esa disposición en los términos indicados. La numeración del precepto no corresponde exactamente a ninguna opción.'}},
{n:119, q:'En el artículo 189.8 del Código Penal se dispone que los jueces y tribunales...', o:{a:'Ordenarán la adopción de las medidas necesarias para la retirada de las páginas web o aplicaciones de internet que contengan o difundan pornografía infantil o en cuya elaboración se hubieran utilizado personas con discapacidad necesitadas de especial protección.',b:'Ordenarán la adopción de las medidas necesarias para bloquear el acceso a las páginas web o aplicaciones de internet que contengan o difundan pornografía infantil o en cuya elaboración se hubieran utilizado personas con discapacidad necesitadas de especial protección, que se encuentren en territorio español.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.189.8 CP: los jueces ordenarán tanto la retirada (a) como el bloqueo de acceso (b) a páginas web con pornografía infantil.'}},
{n:120, q:'Las medidas contenidas en artículo 189.8 del Código Penal, ...', o:{a:'Podrán ser acordadas con carácter cautelar a petición de cualquiera de las partes personadas en el proceso.',b:'Podrán ser acordadas con carácter cautelar, de oficio, por la propia autoridad judicial.',c:'Podrán ser acordadas con carácter cautelar a petición del Ministerio Fiscal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189.8 CP: las medidas pueden acordarse a petición de partes (a), de oficio (b) o a petición del MF (c).'}},
{n:121, q:'Según el artículo 189 bis del Código Penal, constituye delito, la distribución o difusión pública a través de internet, del teléfono, o de cualquier otra tecnología de la información, de contenidos específicamente destinados a ...', o:{a:'Promover la comisión de los delitos previstos en el capítulo V, del Título VIII, del Libro II del Código Penal.',b:'Fomentar la comisión de los delitos previstos en el capítulo II, del Título VIII, del Libro II del Código Penal.',c:'Incitar a la comisión de los delitos previstos en el capítulo IV, del Título VIII, del Libro II del Código Penal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189 bis CP: es delito difundir contenidos para promover (a), fomentar (b) o incitar (c) delitos de los Capítulos II, IV y V del Título VIII.'}},
{n:122, q:'Según el artículo 189 bis del Código Penal, los delitos de distribución o difusión pública a través de internet, del teléfono, o de cualquier otra tecnología de la información, de contenidos específicamente destinados a promover, fomentar o incitar a la comisión de los delitos de los capítulos II, IV y V, del Título VIII, del Libro II del Código Penal...', o:{a:'Se castigan con las penas de prisión de 1 a 3 años y multa de 6 a 12 meses.',b:'Pueden ser castigados con las penas superiores en uno o dos grados cuando concurra alguna de las circunstancias del artículo 189.2 de este Código.',c:'Además de ser castigados con las penas que correspondan, las autoridades judiciales ordenarán la interrupción de los servicios que ofrezcan predominantemente dichos contenidos o para el bloqueo de uno y otros cuando radiquen en el extranjero.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189 bis CP: la pena es 1-3 años y multa (a), puede agravarse con penas superiores (b), y se ordena la interrupción/bloqueo de servicios (c).'}},
{n:123, q:'Según el artículo 189 ter. del Código Penal, cuando una persona jurídica sea responsable de los delitos relativos a la prostitución y a la explotación sexual y corrupción de menores, se le impondrá la pena de...', o:{a:'Multa del triple al quíntuple del beneficio obtenido, si el delito cometido por la persona física tiene prevista una pena de prisión de más de cinco años',b:'Multa del doble al cuádruple del beneficio obtenido, si el delito cometido por la persona física tiene prevista una pena de prisión de más de dos años no incluida en el anterior inciso.',c:'Multa del doble al triple del beneficio obtenido, en el resto de los casos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.189 ter CP: los tres tramos de multa para personas jurídicas en estos delitos son todos correctos.'}},
{n:124, q:'Según el artículo 189 ter. del Código Penal, cuando una persona jurídica sea responsable de los delitos relativos a la prostitución y a la explotación sexual y corrupción de menores, además de la pena de multa que corresponda...', o:{a:'Se impondrá obligatoriamente disolución de la persona jurídica, conforme a lo dispuesto en el artículo 33.7 b) del Código Penal.',b:'Se podrá imponer con carácter facultativo cualquier otra pena de las contenidas en artículo 33.7 CP, atendidas las reglas recogidas en el artículo 66 bis, siempre que sean compatibles con la disolución de la entidad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.189 ter CP: la disolución es obligatoria (a) y pueden imponerse facultativamente otras penas del art.33.7 (b).'}},
{n:125, q:'El Capítulo VI del Título VIII, del Libro II del Código Penal,...', o:{a:'Se denomina "Disposiciones comunes a los títulos anteriores".',b:'Comprende los artículos 190 a 194 bis.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Capítulo VI del Título VIII se denomina "Disposiciones comunes" y comprende los artículos 191 a 194 bis del CP.'}},
{n:126, q:'Según el artículo 190 del Código Penal, la condena de un Juez o Tribunal extranjero, impuesta por cualquiera de los delitos relativos a la prostitución y corrupción de menores:', o:{a:'No vinculará a los tribunales españoles.',b:'Determinará la imposibilidad de actuación de los tribunales españoles.',c:'Será equiparada a las de los jueces y tribunales españoles, a los efectos de aplicación de la agravante de reincidencia.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.190 CP: las condenas de tribunales extranjeros por estos delitos se equiparan a las españolas a efectos de la agravante de reincidencia.'}},
{n:127, q:'Según el artículo 191 del Código Penal, se exige denuncia de la persona agraviada, de su representante legal o querella del Ministerio Fiscal para proceder por el delito de:', o:{a:'Acoso sexual.',b:'Pornografía infantil.',c:'Corrupción de menores.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.191 CP: para proceder por el delito de acoso sexual se requiere denuncia de la persona agraviada, representante legal o querella del MF.'}},
{n:128, q:'Según el artículo 191 del Código Penal, se exige denuncia de la persona agraviada, de su representante legal o querella del Ministerio Fiscal para proceder por el delito de:', o:{a:'Posesión de pornografía infantil para consumo propio.',b:'Asistencia a espectáculos pornográficos, a sabiendas de que participan menores de edad o personas con discapacidad necesitada de especial protección.',c:'Favorecimiento de la prostitución de un menor de edad o persona con discapacidad necesitada de especial protección.',d:'Agresiones sexuales.'}, correct:'d', why:{d:'Art.191 CP: también requiere denuncia el delito de agresiones sexuales (cuando la víctima es mayor de edad y no hay violencia/intimidación).'}},
{n:129, q:'Según el artículo 191 del Código Penal, para proceder por los delitos de agresiones sexuales y acoso sexual bastará denuncia del Ministerio Fiscal...', o:{a:'Cuando la víctima sea menor de edad.',b:'Cuando la víctima sea persona con discapacidad necesitada de especial protección.',c:'Cuando se trate de una persona desvalida.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.191 CP: basta la denuncia del MF cuando la víctima es menor (a), discapacitada (b) o desvalida (c).'}},
{n:130, q:'Según el artículo 191.2 del Código Penal, en los delitos de agresiones sexuales y acoso y acoso sexual, el perdón del ofendido:', o:{a:'Extingue la acción penal.',b:'Extingue la responsabilidad penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.191.2 CP: en los delitos de agresiones sexuales y acoso sexual, el perdón del ofendido NO extingue la acción ni la responsabilidad penal.'}},
{n:131, q:'Según el artículo 191.2 del Código Penal, en los delitos de agresiones sexuales y acoso y acoso sexual, el perdón del ofendido:', o:{a:'Determina la nulidad de lo actuado.',b:'No extingue la responsabilidad penal, ni la responsabilidad de esta clase.',c:'Minora la responsabilidad civil hasta los límites establecidos para los delitos imprudentes.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'d', why:{d:'Art.191.2 CP: el perdón del ofendido no produce ninguno de esos efectos en los delitos de agresiones sexuales y acoso sexual.'}},
{n:132, q:'Con relación a la medida de libertad vigilada, prevista en el artículo 192.1 del Código Penal, indique la respuesta que no es correcta.', o:{a:'Esta medida se impone a los condenados a pena de prisión por uno o más delitos de los comprendidos en el Título VIII del Libro II del Código Penal.',b:'Esta medida de libertad vigilada se ejecutará de manera simultánea a la pena privativa de libertad.',c:'La duración de esta medida será de cinco a diez años, si alguno de los delitos fuera grave, y de uno a cinco años si se trata de uno o más delitos menos graves.',d:'Cuando se trate de un solo delito menos grave, cometido por un delincuente primario, el tribunal podrá imponer o no la medida de libertad vigilada en atención a la menor peligrosidad del autor.'}, correct:'b', why:{b:'La opción b es incorrecta: la libertad vigilada del art.192.1 NO se ejecuta simultáneamente con la pena de prisión, sino DESPUÉS de que se cumpla la pena privativa de libertad.'}},
{n:133, q:'Según el artículo 192.2 del Código Penal, se impone la pena correspondiente en su mitad superior, cuando...', o:{a:'El delito se halle comprendido en el Título VIII del Libro II del Código Penal.',b:'El delito sea cometido por ascendientes, tutores, curadores, guardadores, maestros o cualquier otra persona encargada de hecho o de derecho del menor o persona con discapacidad necesitada de especial protección.',c:'La intervención en el delito se realice como autores o cómplices.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.192.2 CP: la pena en su mitad superior se aplica en todos esos supuestos.'}},
{n:134, q:'Según el artículo 192.3 del Código Penal, en los delitos sexuales de los capítulos I o V, del Título VIII, del Libro II del Código Penal, cuando la víctima sea menor de edad, y en todos los casos del capítulo II de este Título, además de las penas previstas en tales capítulos, se impondrá la pena de privación de la patria potestad o de inhabilitación especial para el ejercicio de los derechos de la patria potestad, tutela, curatela, guarda o acogimiento, por un tiempo ...', o:{a:'2 a 5 años.',b:'4 a 10 años.',c:'3 a 6 años.',d:'4 a 9 años.'}, correct:'b', why:{b:'Art.192.3 CP: la pena adicional de privación de la patria potestad o inhabilitación especial para sus derechos es de 4 a 10 años.'}},
{n:135, q:'Según el artículo 192.3 del Código Penal, en los delitos sexuales que no se hallen comprendidos en los capítulos I o V, del Título VIII, del Libro II del Código Penal, cuando la víctima sea menor de edad, ni en todos los casos del capítulo II de este Título, además de las penas previstas en tales capítulos, se impondrá la pena de privación de la patria potestad o de inhabilitación especial para el ejercicio de los derechos de la patria potestad, tutela, curatela, guarda o acogimiento, por un tiempo ...', o:{a:'1 a 4 años.',b:'4 a 6 años.',c:'6 meses a 6 años.',d:'6 meses a 3 años.'}, correct:'c', why:{c:'Art.192.3 CP: para los delitos sexuales con víctima menor no comprendidos en los caps. I y V, la pena adicional de privación es de 6 meses a 6 años.'}},
{n:136, q:'Según el artículo 192.3 del Código Penal, en los delitos sexuales que no se hallen comprendidos en los capítulos I o V, del Título VIII, del Libro II del Código Penal, cuando la víctima sea menor de edad, ni en todos los casos del capítulo II de este Título, además de las penas previstas en tales capítulos, se impondrá la pena de inhabilitación especial para empleo o cargo público o ejercicio de la profesión u oficio, retribuido o no, por un tiempo de...', o:{a:'6 meses a 6 años.',b:'3 meses a 3 años.',c:'2 a 5 años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.192.3 CP: la inhabilitación especial para empleo/profesión en estos supuestos es de 6 meses a 6 años.'}},
{n:137, q:'Según el artículo 192.3 del Código Penal, la autoridad judicial impondrá a las personas responsables de los delitos comprendidos en el Título VIII del Libro II, sin perjuicio de las penas que correspondan, una pena de inhabilitación especial para cualquier profesión, oficio o actividades, sean o no retribuidos, que conlleve contacto regular y directo con personas menores de edad...', o:{a:'Por un tiempo superior entre 5 y 20 años al de la duración de la pena de privación de libertad impuesta en la sentencia si el delito fuera grave.',b:'Por un tiempo entre 2 y 20 años si el delito fuera menos grave.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.192.3 CP: la inhabilitación especial para profesiones con contacto con menores es de 5-20 años si el delito es grave (a) y de 2-20 años si es menos grave (b).'}},
{n:138, q:'Dispone el artículo 193 del Código Penal que en las sentencias condenatorias por delitos contra la libertad sexual, además del pronunciamiento correspondiente a la responsabilidad civil, se harán, en su caso...', o:{a:'Los pronunciamientos que procedan en orden a la filiación.',b:'Los pronunciamientos que procedan en orden a la fijación de alimentos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.193 CP: en delitos contra la libertad sexual, además de la responsabilidad civil, se harán pronunciamientos sobre filiación (a) y alimentos (b).'}},
{n:139, q:'Dispone el artículo 194 del Código Penal que, cuando se utilizaren establecimientos o locales, abiertos o no al público, se decretará en la sentencia condenatoria su clausura definitiva. Esta previsión es aplicable a los delitos de...', o:{a:'Acoso sexual.',b:'Prostitución de menores.',c:'Violación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.194 CP: la clausura definitiva de locales se aplica a todos los delitos del Título VIII, incluyendo acoso sexual, prostitución de menores y violación.'}},
{n:140, q:'Dispone el artículo 194 del Código Penal que, cuando se utilizaren establecimientos o locales, abiertos o no al público, se decretará en la sentencia condenatoria su clausura definitiva. Esta previsión es aplicable a los delitos de...', o:{a:'Agresiones sexuales a menores de 16 años.',b:'Exhibicionismo y provocación sexual.',c:'Atentados contra la integridad moral.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.194 CP: la clausura definitiva aplica a todos los delitos del Título VIII, incluyendo agresiones a menores (a) y exhibicionismo (b). Los atentados contra la integridad moral son del Título VII, pero el art.194 se aplica solo al Título VIII.'}},
{n:141, q:'Dispone el artículo 194 del Código Penal que, cuando se utilizaren establecimientos o locales, abiertos o no al público, se decretará en la sentencia condenatoria su clausura definitiva. Esta previsión es aplicable a los delitos de...', o:{a:'Los capítulos IV y V, del Título VIII, del Libro II del Código Penal.',b:'Los capítulos I y II, del Título VIII, del Libro II del Código Penal.',c:'Los capítulos III, IV y V, del Título VIII, del Libro II del Código Penal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.194 CP: la clausura definitiva se aplica a todos los delitos del Título VIII (no solo algunos capítulos), por lo que ninguna de las opciones a, b, c es correcta.'}},
{n:142, q:'El artículo 194 bis del Código Penal dispone que las penas previstas se impondrán sin perjuicio las que pudieran corresponder por los actos de violencia física o psíquica que se realizasen. Esta previsión es aplicable...', o:{a:'A todos los delitos comprendidos en los capítulos I y II, del Título VIII, del Libro II del Código Penal.',b:'A todos los delitos comprendidos en los capítulos IV y V, del Título VIII, del Libro II del Código Penal.',c:'A todos los delitos comprendidos en todos los capítulos del Título VIII, del Libro II del Código Penal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.194 bis CP: la acumulación de penas por actos de violencia física o psíquica se aplica a todos los delitos comprendidos en el Título VIII del Libro II del CP.'}},
];
